SELECT s.id, s.media_id, s.app_id, s.name, s.name_alise, s.ad_scene, s.ad_size, s.ssp_pay_type, s.ssp_deal_ratio, s.fixed_price, s.ad_image, s.enable, s.creator, s.create_time, s.updater, s.update_time, s.deleted, s.tenant_id, m.media_company_short as mediaShortName, m.media_company_short as mediaName, a.access_type as accessType, a.name as appName, a.os_type as osType, s.name_alise as sspName
FROM ssp_slot_info as s LEFT JOIN ssp_media as m ON m.id = s.media_id AND m.enable = 1 LEFT JOIN ssp_app as a ON a.id = s.app_id AND a.enable = 1
AND s.id IN
#{rid}
AND s.media_id = #{reqVO.mediaId}
AND s.app_id IN
#{aid}
AND
s.name LIKE CONCAT('%', #{n}, '%')
AND
s.name_alise LIKE CONCAT('%', #{na}, '%')
AND s.ad_scene = #{reqVO.adScene}
AND a.os_type = #{reqVO.osType}
AND s.ssp_pay_type = #{reqVO.sspPayType}
AND s.enable = #{reqVO.enable}
AND s.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}
AND s.update_time BETWEEN #{reqVO.updateTime[0]} AND #{reqVO.updateTime[1]}
ORDER BY s.id DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*)
FROM ssp_slot_info as s
    LEFT JOIN ssp_media as m
        ON  m.id = s.media_id AND m.enable = 1
    LEFT JOIN ssp_app as a
        ON a.id = s.app_id AND a.enable = 1


